CREATE TABLE IF NOT EXISTS abbreviations (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, category_slug TEXT NOT NULL, meaning_bn TEXT NOT NULL, description_bn TEXT NOT NULL, icon TEXT NOT NULL DEFAULT '📖', tag TEXT NOT NULL DEFAULT '', created_at TEXT, updated_at TEXT);
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('SBL','Smart Business Link','E-Commerce Core','ecommerce','SBL E-Commerce & Dropshipping Ecosystem','SBL is a comprehensive business platform operating dropshipping, merchant networks, and member back-offices.','🌐','Ecosystem');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('COD','Cash On Delivery','E-Commerce Core','ecommerce','Payment delivery model where payment is made upon receipt','The customer pays the full parcel amount to the delivery rider upon receiving the product. Approx 90% of local e-commerce sales use COD.','💵','Payment');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('SKU','Stock Keeping Unit','E-Commerce Core','ecommerce','Unique product identification code','Unique alphanumeric code used in inventory management to track distinct product variants like size, color, or model.','🏷️','Inventory');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('AOV','Average Order Value','E-Commerce Core','ecommerce','Average Order Value','Calculated by dividing total sales revenue by total number of orders (Total Revenue / Total Orders).','📊','Revenue');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MOQ','Minimum Order Quantity','E-Commerce Core','ecommerce','Minimum Order Quantity','The lowest quantity of units a supplier requires for purchase. Dropshipping typically eliminates MOQ restrictions.','📦','Sourcing');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('B2B','Business to Business','E-Commerce Core','ecommerce','Business to Business transactions','Commercial transactions where suppliers or manufacturers sell goods directly to dropshippers, merchants, or wholesalers.','🏢','Model');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('B2C','Business to Consumer','E-Commerce Core','ecommerce','Direct sales from business to retail consumers','Sales model where dropshippers sell goods directly to individual end-users via social media or e-commerce websites.','🛍️','Model');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('D2C','Direct to Consumer','E-Commerce Core','ecommerce','Direct to Consumer brand model without intermediaries','Selling brand products directly to consumers through an owned website or sales funnel without third-party marketplace dependence.','🎯','Brand');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MR','Merchant Reseller','E-Commerce Core','ecommerce','Merchant Reseller or dropship partner','Registered partner on the SBL platform marketing products without holding physical inventory to earn profit margins.','🤝','Partner');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('RTO','Return To Origin','Logistics & Delivery','logistics','Return to Origin when parcel delivery fails','If a customer refuses delivery or cannot be reached, the courier returns the parcel to the warehouse. Reducing RTO is vital for profitability.','🔄','Courier');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('NDR','Non-Delivery Report','Logistics & Delivery','logistics','Non-Delivery Report with failed delivery reasons','Report raised on courier portals when a rider fails delivery or the customer requests delivery postponement.','⚠️','Courier');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('AWB','Air Waybill / Consignment Tracking Number','Logistics & Delivery','logistics','Air Waybill / Consignment Tracking Number','Unique barcode and number assigned to every parcel enabling real-time status and transit tracking by customers and merchants.','🚚','Tracking');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('3PL','Third-Party Logistics','Logistics & Delivery','logistics','Third-Party Logistics service provider','External logistics companies providing warehousing, packaging, and door-to-door delivery services (e.g. Steadfast, RedX, Paperfly).','📦','Logistics');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('TAT','Turnaround Time','Logistics & Delivery','logistics','Turnaround Time from order placement to final delivery','Total turnaround duration measured in hours or days between order confirmation and successful doorstep delivery.','⏱️','Speed');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('SLA','Service Level Agreement','Logistics & Delivery','logistics','Service Level Agreement for logistics delivery timelines','Contractual standard between merchants and couriers defining required pickup, transit, and delivery performance windows.','📝','Standard');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('POD','Proof of Delivery','Logistics & Delivery','logistics','Proof of Delivery confirmation','Digital proof including customer signature, OTP verification, or parcel receipt confirmation upon delivery completion.','✅','Delivery');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('ROAS','Return On Ad Spend','Marketing & Ads','marketing','Return On Ad Spend (Revenue ÷ Ad Spend)','Marketing metric measuring revenue generated per currency unit spent on advertising (e.g., 20,000 revenue on 5,000 ad spend = 4X ROAS).','🎯','Efficiency');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CPA','Cost Per Acquisition / Action','Marketing & Ads','marketing','Cost Per Acquisition or action','Total advertising spend divided by total confirmed orders (Ad Spend ÷ Total Orders).','💳','Cost');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CPM','Cost Per Mille (Per 1,000 Impressions)','Marketing & Ads','marketing','Cost Per Mille (Per 1,000 Impressions)','The advertising cost charged by platforms like Meta or Google to display an ad to 1,000 user feeds.','👁️','Impression');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CPC','Cost Per Click','Marketing & Ads','marketing','Cost Per Click','Average advertising cost each time a prospective customer clicks on an ad to visit the store or landing page.','🖱️','Traffic');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CTR','Click-Through Rate','Marketing & Ads','marketing','Click-Through Rate','(Total Clicks ÷ Total Impressions) × 100. Measures ad creative engagement and appeal. A 2%+ CTR is widely considered good in dropshipping.','📈','Performance');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CVR','Conversion Rate','Marketing & Ads','marketing','Conversion Rate','(Total Orders ÷ Total Landing Page Visitors) × 100. For instance, 3 orders out of 100 visitors represents a 3% conversion rate.','🛒','Conversion');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('LP','Landing Page','Marketing & Ads','marketing','Dedicated product sales Landing Page','Single-focus web page optimized with product details, customer reviews, and order forms where ad traffic is directed.','📄','Web');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('UGC','User Generated Content','Marketing & Ads','marketing','User Generated Content','Customer-created unboxing videos, photos, and testimonial reviews that deliver higher trust and conversion rates in ad campaigns.','📱','Creative');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('CAC','Customer Acquisition Cost','Marketing & Ads','marketing','Customer Acquisition Cost','Comprehensive financial cost to acquire a new paying customer, factoring in ad spend, software tools, and operational overhead.','👥','Finance');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('LTV','Lifetime Value (CLV)','Marketing & Ads','marketing','Customer Lifetime Value (CLV)','The total cumulative revenue a customer is projected to generate for your business across their entire relationship.','💎','Retention');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('BV','Business Volume','SBL Network & System','network','Business Volume points for commission calculation','Standardized point metric assigned to products and membership packages in SBL to calculate pair and matching commissions.','⚡','Commission');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('PV','Point Value','SBL Network & System','network','Point Value for rank advancement','Numeric points attached to package enrollments used for tracking leadership rank qualifications and team milestone incentives.','⭐','Points');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('KYC','Know Your Customer','SBL Network & System','network','Know Your Customer identity verification','Verification procedure validating national identity documents (NID) and contact numbers for member account activation.','🛡️','Security');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MB','Matching Bonus','SBL Network & System','network','Matching Bonus on binary team balance','Automated commission credited when sales volume points match across Left and Right binary branches.','⚖️','Bonus');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('GB','Generation Bonus','SBL Network & System','network','Generation Bonus across multi-tier networks','Tiered commission and royalty rewards earned from active production across multi-generation referred downline networks.','🌳','Bonus');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('ROI','Return On Investment','SBL Network & System','network','Return On Investment','Net percentage financial return earned weekly or monthly on capital invested in SBL crowdfunding or dropshipping packages.','💰','Investment');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('OTP','One-Time Password','SBL Network & System','network','One-Time Password security code','Temporary security authentication code sent via SMS for withdrawal authorization and sensitive account actions.','🔐','Security');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('COGS','Cost Of Goods Sold','Finance & Operations','finance','Cost Of Goods Sold','Direct cost incurred to source or manufacture a product before advertising (Selling Price - COGS = Gross Profit).','🧾','Accounting');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('P&L','Profit and Loss Statement','Finance & Operations','finance','Profit and Loss financial statement','Comprehensive summary of gross revenues minus COGS, ad spend, operational costs, and courier return charges to determine net profit.','📉','Finance');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('MFS','Mobile Financial Services','Finance & Operations','finance','Mobile Financial Services payment channel','Digital wallet channels (bKash, Nagad, Rocket) used for commission payouts, customer payments, and merchant settlements.','📲','Payment');
INSERT OR IGNORE INTO abbreviations (code,name,category,category_slug,meaning_bn,description_bn,icon,tag) VALUES ('POS','Point Of Sale','Finance & Operations','finance','Point Of Sale cashier system','Retail software and counter system for barcode scanning, order invoicing, and immediate transactional checkout.','🖥️','Software');
